// DRY: the discount rule lives in one place
public final class Discount {
    // Money: BigDecimal, never double (0.1 + 0.2 != 0.3 in double)
    public static BigDecimal apply(BigDecimal amount, BigDecimal percent) {
        BigDecimal factor = BigDecimal.ONE.subtract(percent.movePointLeft(2));
        return amount.multiply(factor).setScale(2, RoundingMode.HALF_EVEN);
    }
}

