// Access control: the query already filters by the owner
@GetMapping("/orders/{id}")
OrderResponse get(@PathVariable Long id, @AuthenticationPrincipal Jwt jwt) {
    // another customer's order = 404 (does not reveal that it exists)
    Order order = repository.findByIdAndCustomerId(id, jwt.getSubject())
        .orElseThrow(() -> new OrderNotFoundException(id));
    return OrderResponse.from(order);
}

